//! Independent held hammer conversion through registered typed World actions.
use gielinor_world::{held_item_conversion::Rule,inventory::Item,simulation::{World,PlayerData,ActorId,Action,WorldEvent},stats::Stats,hits::{Hit,Target,Style},CoordGrid};
fn fixture(reverse:bool,member:bool,selected:usize,sparse:bool)->(World,ActorId,i32,i32){let(input,output)=if reverse{(29775,25644)}else{(25644,29775)};let mut w=World::default();w.collision.allocate(3200,3200,0);for(a,b)in[(25644,29775),(29775,25644)]{w.empty_containers.insert(a,Rule{output:b,members:false,button_operation:4,message:None});}let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_current(12,0);let mut d=PlayerData::new(1,"Independent held hammer".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:1931,count:1,vars:0})).unwrap();}let duplicate=(selected+1)%28;for s in[selected,duplicate]{d.inventory.restore_slot(s,Some(Item{id:input,count:1,vars:0})).unwrap();}if sparse{for s in(0..28).filter(|s|*s!=selected && *s!=duplicate).take(3){d.inventory.restore_slot(s,None).unwrap();}}d.equipment.restore_slot(0,Some(Item{id:1129,count:1,vars:7})).unwrap();w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,member).unwrap();w.tick().unwrap();w.drain_events();w.data_mut(a).unwrap().inventory.clear_modified();(w,a,input,output)}
#[test]fn four_held_swaps_cancel_preexisting_weak_crafting_without_credit(){use gielinor_world::{grinding,tool_crafting::Recipe,held_use::{Handler,Scope,Type,Request}};let mut n=0;for reverse in[false,true]{for member in[false,true]{let(mut w,a,input,output)=fixture(reverse,member,17,false);{let d=w.data_mut(a).unwrap();d.stats.set_base(12,99);d.stats.set_current(12,99);d.stats.set_fine_xp(12,130344311).unwrap();for(s,id)in[(0,1755),(1,1755),(8,1623),(26,1623)]{d.inventory.restore_slot(s,Some(Item{id,count:1,vars:0})).unwrap();}}let recipe=Recipe{skill:12,exchange:grinding::Recipe{tool:1755,input:1623,output:1607,members:false,animation:Some(8833)},level:20,xp_tenths:500,output_count:1,ticks:10,name:"independent weak-work control",action:"cut",failure:None};for id in[1755,1623]{w.held_use_types.insert(id,Type{id,content:-1});}w.held_use_handlers.register(Scope::Types,1755,1623,Handler::ToolCrafting(recipe)).unwrap();let held=Request{selected_slot:0,selected_id:1755,target_slot:8,target_id:1623};assert!(w.prepare_held_use(a,held).unwrap().is_some());w.finish_held_use(a,held).unwrap();assert!(w.take_tool_crafting_request(a).unwrap().is_none());let before=w.data(a).unwrap().clone();let mut expected=before.inventory.clone();expected.restore_slot(17,Some(Item{id:output,count:1,vars:0})).unwrap();w.drain_events();w.submit(a,Action::ConvertHeldItem{slot:17,item:input}).unwrap();for _ in 0..20{w.tick().unwrap();assert_eq!(w.data(a).unwrap().inventory,expected);assert_eq!(w.data(a).unwrap().stats,before.stats);assert_eq!(w.data(a).unwrap().equipment,before.equipment);}assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{..})));n+=1;}}assert_eq!(n,4);println!("PG_IMCANDO_HELD weak_work_cancelled={n};10tick synthetic queue is interruption control,not gem cadence acceptance");}
